import{_ as o,C as r,o as n,c as s,j as t,a as i,E as d,a2 as h}from"./chunks/framework.CGSzHL4z.js";const w=JSON.parse('{"title":"The Inspector","description":"","frontmatter":{},"headers":[],"relativePath":"features/inspector.md","filePath":"features/inspector.md","lastUpdated":1792710555000}'),c={name:"features/inspector.md"};function l(p,e,u,m,y,b){const a=r("Screenshot");return n(),s("div",null,[e[0]||(e[0]=t("h1",{id:"the-inspector",tabindex:"-1"},[i("The Inspector "),t("a",{class:"header-anchor",href:"#the-inspector","aria-label":'Permalink to "The Inspector"'},"​")],-1)),e[1]||(e[1]=t("p",null,"The Inspector shows the settings of whatever you selected last and lets you key them. Pick a part of an actor and you get its properties, each with a key diamond. Press a key, a block, a marker or a camera shot on the Timeline and you get that item's panel instead. Use it whenever you want to animate a value that isn't a pose: a light's brightness, a particle's colour, a camera's field of view.",-1)),d(a,{name:"insp-sparks",caption:"The Inspector on a ParticleEmitter named Sparks: the Calls section with Emit and Clear, Appearance with a keyed Color gradient bar and a Size curve thumbnail, a key diamond on every row, and the search box at the top."}),e[2]||(e[2]=h('<h2 id="opening-it" tabindex="-1">Opening it <a class="header-anchor" href="#opening-it" aria-label="Permalink to &quot;Opening it&quot;">​</a></h2><p>The Inspector is a tab in the Hub. Right click the tab and choose <strong>Pop out Inspector</strong> to give it a window of its own; right click it again in that window, or click the return button at the right of its tab strip, to send it back.</p><p>Pressing something on the Timeline (a block, a marker, a switch key, a spawned actor&#39;s Lifetime bar) switches the Hub to the Inspector tab. Selecting things in Studio&#39;s Explorer or clicking a row header never switches tabs. When the Inspector tab is hidden and what it would show changes, the tab gets a small accent dot.</p><h2 id="what-it-shows" tabindex="-1">What it shows <a class="header-anchor" href="#what-it-shows" aria-label="Permalink to &quot;What it shows&quot;">​</a></h2><p>The last selection wins. Whatever you select afterwards (keys, rows, a viewport pick, a Studio selection inside an actor) takes the Inspector over.</p><table tabindex="0"><thead><tr><th>You select</th><th>The Inspector shows</th></tr></thead><tbody><tr><td>An actor row, a joint, the root, a property row, or a part in the viewport</td><td>The property panel for that instance</td></tr><tr><td>Keys</td><td>The Key panel: frame, value, key type and interpolation</td></tr><tr><td>An action block, generator, constraint, driver or Motion Warp</td><td>That block&#39;s panel</td></tr><tr><td>A marker flag, a camera shot, an attach key</td><td>The Marker, Camera switch or Attach panel</td></tr><tr><td>A layer or a version</td><td>The layer panel or the Version panel</td></tr><tr><td>An audio clip or a lane header</td><td>The clip or lane panel</td></tr></tbody></table><p>Every panel that shows one thing (a block, a clip, a marker, a switch key) has a trash button in its header that deletes it, with the same <strong>Delete</strong> on a right click of the header.</p><h2 id="the-property-panel" tabindex="-1">The property panel <a class="header-anchor" href="#the-property-panel" aria-label="Permalink to &quot;The property panel&quot;">​</a></h2><p>The header has the instance&#39;s class icon, its name and a class chip. Under it, the <strong>picker</strong> shows the instance&#39;s path inside the actor. Click it for a searchable tree of everything in the actor, with a count of animated properties on each instance.</p><p><strong>Search properties</strong> searches the whole actor. This instance&#39;s matches come first, then &quot;Elsewhere on {actor}&quot; with a <strong>Show</strong> arrow that jumps to the other instance. The key button beside the search is <strong>Animated only</strong>: it lists just the properties with keys, on every instance of the actor, and stays on until you turn it off.</p><p>Properties are grouped by Studio category, A to Z inside each, in sections that fold (remembered per class). A <strong>Calls</strong> section comes first on objects with methods, and <strong>Attributes</strong> comes last. The <strong>Game target</strong>, <strong>Attached</strong> and <strong>Stack</strong> sections sit at the end. Rows that can&#39;t be animated are left out: read-only and deprecated properties, BrickColor, Font, PhysicalProperties and velocities. On a part inside a rig, Position and Rotation aren&#39;t listed, because you pose that part in the viewport.</p><h3 id="editors-by-type" tabindex="-1">Editors by type <a class="header-anchor" href="#editors-by-type" aria-label="Permalink to &quot;Editors by type&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Type</th><th>Editor</th></tr></thead><tbody><tr><td>Number</td><td>A field you drag to scrub or click to type</td></tr><tr><td>Vector2, Vector3, UDim, UDim2</td><td>One field per part</td></tr><tr><td>NumberRange</td><td>One field (<code>2</code>, <code>1 5</code> or <code>1-5</code>); the chevron splits it into Min and Max</td></tr><tr><td>Bool, Enum, Text</td><td>A toggle, a menu, a text box</td></tr><tr><td>Color3</td><td>A swatch and a hex field; the swatch opens the <a href="./colors-and-sequences">colour picker</a></td></tr><tr><td>NumberSequence, ColorSequence</td><td>A preview that opens the sequence or gradient editor, plus a one-value control before it</td></tr><tr><td>Asset (images, textures, sounds)</td><td>A thumbnail, an id field and a palette of images the track and actor already use</td></tr></tbody></table><p>Number fields work the same everywhere. Drag past 3 px to scrub, hold <code>Shift</code> for 10x finer steps or <code>Ctrl</code> for whole numbers, and press <code>Esc</code> to put the value back. A click without a drag types, and you can type arithmetic on the value shown: <code>+5</code>, <code>*2</code>, <code>/2</code>, <code>-=3</code>.</p><h3 id="key-diamonds" tabindex="-1">Key diamonds <a class="header-anchor" href="#key-diamonds" aria-label="Permalink to &quot;Key diamonds&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Diamond</th><th>Means</th><th>Click it to</th></tr></thead><tbody><tr><td>Hollow</td><td>Not animated</td><td>Add a track and key the current value</td></tr><tr><td>Bottom half filled</td><td>Animated, no key on this frame</td><td>Key it here</td></tr><tr><td>Filled</td><td>Keyed on this frame</td><td>Remove this key (the track stays)</td></tr><tr><td>Orange</td><td>Changed, not keyed yet</td><td>Key the change</td></tr></tbody></table><p><code>K</code> with the pointer over a row keys it too. With a track and Auto-key on, editing a value keys it at the playhead. With Auto-key off, the change is a temporary pose that the next playhead move drops. A property with no track changes the instance for good, as one undo step.</p><p>Edits you make in Studio&#39;s own Properties window to a property that already has a track are recorded the same way.</p><h3 id="row-menu-and-copying-values" tabindex="-1">Row menu and copying values <a class="header-anchor" href="#row-menu-and-copying-values" aria-label="Permalink to &quot;Row menu and copying values&quot;">​</a></h3><p>Right click anywhere on a row for Key at playhead, Remove from timeline, Copy, Paste, Reset to default and Reset to value before animating. <code>Shift+C</code> copies the value of the row under the pointer and <code>Shift+V</code> pastes it onto another row of the same type. <strong>Paste as driver</strong> turns the copied property into a Copy <a href="./constraints-and-drivers#drivers">driver</a> on this one.</p><h3 id="calls-and-attributes" tabindex="-1">Calls and attributes <a class="header-anchor" href="#calls-and-attributes" aria-label="Permalink to &quot;Calls and attributes&quot;">​</a></h3><p>The Calls section keys methods as events: an emitter&#39;s <code>Emit()</code> (with a Count from 1 to 50 and an optional Life), a sound&#39;s <code>Play()</code> (with Count and Stop at), and <code>Stop()</code>, <code>Clear()</code> and <code>Pause()</code>. See <a href="./blocks-and-audio">Action blocks, events and audio</a> for how they draw on the Timeline.</p><p>The <strong>+</strong> on the Attributes header adds an attribute of any type Roblox allows. Attributes animate like properties, in rows named <code>@Name</code>. An Instance attribute holds a reference, so it has no key diamond.</p><h2 id="editing-several-objects" tabindex="-1">Editing several objects <a class="header-anchor" href="#editing-several-objects" aria-label="Permalink to &quot;Editing several objects&quot;">​</a></h2><p>Select keys on several objects, several Timeline rows, or up to 500 instances in Studio, and the header reads &quot;ParticleEmitter ×3&quot;. Values that differ read <strong>Mixed</strong>. Typing sets only the part you changed on every object, dragging moves each by the same amount, and the whole edit is one undo step. A half-filled diamond means only some objects have a key here (&quot;2 of 3 objects have a key here&quot;). Objects of different classes show only the properties they share.</p><h2 id="tips" tabindex="-1">Tips <a class="header-anchor" href="#tips" aria-label="Permalink to &quot;Tips&quot;">​</a></h2><ul><li>While the Timeline plays or scrubs, values and diamonds follow the playhead up to 20 times a second and show the exact frame once it stops.</li><li>The Inspector remembers which sections you folded, in every kind of panel.</li><li>Picking an actor as a whole scrolls to its Stack section, which lists every generator, constraint, driver and warp on the actor in the order they run.</li></ul><h2 id="compared-to-roblox-s-animation-editor" tabindex="-1">Compared to Roblox&#39;s Animation Editor <a class="header-anchor" href="#compared-to-roblox-s-animation-editor" aria-label="Permalink to &quot;Compared to Roblox&#39;s Animation Editor&quot;">​</a></h2><p>Roblox&#39;s Animation Editor animates a rig&#39;s joints and face. It has no way to key a light&#39;s Brightness, a ParticleEmitter&#39;s Color or a camera&#39;s FieldOfView. You can change those in Studio&#39;s Properties window, but the change isn&#39;t keyed. The AcesMotion Inspector gives those properties key diamonds, along with attributes and method calls, on any instance in the scene&#39;s cast.</p>',29))])}const f=o(c,[["render",l]]);export{w as __pageData,f as default};
